# ---------------------------------------------------------------------------
# SCRIPT LOGIC
# ---------------------------------------------------------------------------

def load_data(path):
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def save_data(path, data):
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def update_figures(data):
    figures = data.get('figures', [])
    updated = 0
    for fig in figures:
        fid = fig.get('id')
        if fid in FIGURE_UPDATES:
            patch = FIGURE_UPDATES[fid]
            name = fig.get('name', str(fid))
            old_essay_len = len(fig.get('essay') or '')
            if 'essay' in patch:
                fig['essay'] = patch['essay']
            if 'key_works' in patch:
                fig['key_works'] = patch['key_works']
            new_essay_len = len(fig.get('essay') or '')
            print(f"  FIGURE id={fid} '{name}': essay {old_essay_len} → {new_essay_len} chars")
            updated += 1
    return updated


def update_scholars(data):
    scholars = data.get('scholars', [])
    updated = 0
    for sch in scholars:
        sid = sch.get('id')
        if sid in SCHOLAR_UPDATES:
            patch = SCHOLAR_UPDATES[sid]
            name = sch.get('name', str(sid))
            old_essay_len = len(sch.get('essay') or '') if 'essay' in sch else 0
            if 'essay' in patch:
                sch['essay'] = patch['essay']
            if 'key_works' in patch:
                sch['key_works'] = patch['key_works']
            new_essay_len = len(sch.get('essay') or '')
            print(f"  SCHOLAR id={sid} '{name}': essay {old_essay_len} → {new_essay_len} chars")
            updated += 1
    return updated


def main():
    path = os.path.abspath(DATA_PATH)
    print(f"Loading data from: {path}")
    data = load_data(path)

    print(f"\nUpdating figures ({len(FIGURE_UPDATES)} targets)...")
    fig_count = update_figures(data)

    print(f"\nUpdating scholars ({len(SCHOLAR_UPDATES)} targets)...")
    sch_count = update_scholars(data)

    print(f"\nSaving data to: {path}")
    save_data(path, data)

    print(f"\nDone. Updated {fig_count} figures and {sch_count} scholars.")


if __name__ == '__main__':
    main()
